import{_ as t,o as s,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"定投搜索的一点小更新","description":"","frontmatter":{"date":"2023-05-06T19:27:48","title":"定投搜索的一点小更新","categories":["定投人生课堂","定投搜索","Mixin机器人"],"tags":["定投人生课堂","定投搜索","Mixin机器人"]},"headers":[],"relativePath":"posts/course100/010.md","filePath":"posts/course100/010.md"}'),c={name:"posts/course100/010.md"};function i(d,e,p,r,l,n){return s(),o("div",null,[...e[0]||(e[0]=[a('<p>对定投搜索来说，每接收到一条消息（输入），实际上是一条命令，因此对接收的消息做了一个格式化：所有输入将格式化成 <code>/命令 参数</code> (<code>/command args</code> )的格式。</p><p>目前支持的 <code>command</code> 有：</p><ul><li><code>/s</code>，检索课程并返回课程清单。</li><li><code>/d</code>，检索课程并返回课程卡片。</li><li><code>/thx</code>，返回感谢列表，感谢列表是不定期更新的。</li></ul><p>当发送的消息不包含命令时，会默认加上 <code>/s</code> 命令，这样可以减少输入，如发送的消息是「极客」时，等同于发送「/s 极客」。</p><p>命令的先后顺序无关，如发送以下消息，效果是一样的：「/s 极客 测试」，「极客 /s 测试」，「极客 测试 /s」。</p><p>如果发送了不支持的命令格式，不会返回任何消息，只会将消息设置为已读状态。</p><p>以下是一些命令截图：</p><p><img src="https://assets.quill.im/5hfvkbqezcwletv35bo7uac7xa9d" alt="image.png"><br><img src="https://assets.quill.im/lioaqbdg1wp2nvbcdhqumbtr4l2l" alt="WechatIMG244.png"><br> 战友们可以自行尝试，如果发现工具的问题，可以添加我的微信「Crazy_Airhead」，或Mixin号「1091586」，进行反馈，谢谢。</p>',8)])])}const u=t(c,[["render",i]]);export{m as __pageData,u as default};
